package io.invenlio.catalog;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="catalog_brands") class Brand {
 enum Status{ACTIVE,ARCHIVED} @Id private UUID id; @Column(name="tenant_id",updatable=false) private UUID tenantId; private String name; private String slug; @Column(name="normalized_name") private String normalizedName; @Enumerated(EnumType.STRING) private Status status; @Column(name="created_at",updatable=false) private Instant createdAt; @Column(name="updated_at") private Instant updatedAt; @Version private long version;
 protected Brand(){} Brand(UUID tenant,String name){id=UUID.randomUUID();tenantId=tenant;setName(name);status=Status.ACTIVE;createdAt=updatedAt=Instant.now();} void update(String n,long expected){if(version!=expected)throw new CatalogException("CONCURRENT_MODIFICATION","Brand was modified");if(status==Status.ARCHIVED)throw new CatalogException("BRAND_ARCHIVED","Archived brand is immutable");setName(n);updatedAt=Instant.now();} void archive(){status=Status.ARCHIVED;updatedAt=Instant.now();} private void setName(String n){name=CatalogRules.required(n,"name",120);normalizedName=CatalogRules.normalized(name);slug=CatalogRules.slug(name);} UUID id(){return id;} String name(){return name;} String slug(){return slug;} Status status(){return status;} Instant created(){return createdAt;} Instant updated(){return updatedAt;} long version(){return version;}
}
